const { useState, useEffect } = React;
const root = ReactDOM.createRoot(document.querySelector('#root'));

const notices = ['신상품 20% 할인', '무료 배송 이벤트', '신규 코스 오픈'];

// 정리를 하지 않았습니다. 무엇이 잘못되는지 보려고 그대로 두었습니다.
const Banner = () => {
  const [index, setIndex] = useState(0);

  useEffect(() => {
    console.log('배너를 켭니다');
    setInterval(() => {
      console.log('   배너 넘김');
      setIndex((i) => (i + 1) % notices.length);
    }, 1500);
  }, []);

  return (
    <div className="banner">
      <p className="banner__text">{notices[index]}</p>
      <p className="banner__step">{index + 1} / {notices.length}</p>
    </div>
  );
};

const App = () => {
  const [shown, setShown] = useState(true);

  return (
    <div className="panel">
      {shown ? <Banner /> : <p className="off">배너를 껐습니다</p>}
      <div className="row">
        <button className="hide" type="button" onClick={() => setShown(false)}>배너 끄기</button>
        <button className="show" type="button" onClick={() => setShown(true)}>배너 켜기</button>
      </div>
    </div>
  );
};

root.render(<App />);

